import json
import time

products = [
  {"id": 1, "name": 'Laptop', "category": 'electronics', "price": 999},
  {"id": 2, "name": 'Shirt', "category": 'clothing', "price": 29},
  {"id": 3, "name": 'Phone', "category": 'electronics', "price": 699},
  {"id": 4, "name": 'Jeans', "category": 'clothing', "price": 59},
  {"id": 5, "name": 'Tablet', "category": 'electronics', "price": 399},
  {"id": 6, "name": 'Hat', "category": 'clothing', "price": 19}
]

def filterByCategory(productList, category):
  return [p for p in productList if p["category"] == category]

def searchByName(productList, query):
  return [p for p in productList if query.lower() in p["name"].lower()]

def sortByPriceAsc(productList):
  return sorted(productList, key=lambda p: p["price"])

def filterProducts(filters):
  result = list(products)
  if filters.get("category"):
    result = filterByCategory(result, filters["category"])
  if filters.get("search"):
    result = searchByName(result, filters["search"])
  if filters.get("sort") == "asc":
    result = sortByPriceAsc(result)
  return result

class FilterCache:
  def __init__(self, ttl=60):
    self.cache = {}
    self.ttl = ttl

  def cachedFilter(self, filters):
    key = json.dumps(filters, sort_keys=True)
    entry = self.cache.get(key)
    if entry and entry["expiresAt"] > time.time():
      print("cache hit")
      return entry["result"]
    print("cache miss")
    result = filterProducts(filters)
    self.cache[key] = {"result": result, "expiresAt": time.time() + self.ttl}
    return result

cache = FilterCache()
# First call should miss
print(json.dumps(cache.cachedFilter({"category": "clothing", "sort": "asc"})))
# Second call with same params should hit
print(json.dumps(cache.cachedFilter({"category": "clothing", "sort": "asc"})))
